static inline MDD
lddmc_refs_push(MDD ldd)
{
    LOCALIZE_THREAD_LOCAL(lddmc_refs_key, lddmc_refs_internal_t);
    if (lddmc_refs_key->r_count >= lddmc_refs_key->r_size) {
        lddmc_refs_key->r_size *= 2;
