    }
    lddmc_refs_key->spawns[lddmc_refs_key->s_count++] = t;
}

static inline MDD
lddmc_refs_sync(MDD result)
{
    LOCALIZE_THREAD_LOCAL(lddmc_refs_key, lddmc_refs_internal_t);
    lddmc_refs_key->s_count--;
